import{z as s,x as B,o as t,c as d,q as r,j as A,D as E,d as n,s as o,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"交错 DiD","description":"","frontmatter":{"title":"交错 DiD","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/staggered-did.md","filePath":"econ/staggered-did.md","lastUpdated":1791413859000}'),m={name:"econ/staggered-did.md"};function p(D,a,T,c,h,u){const i=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="交错-did" tabindex="-1">交错 DiD <a class="header-anchor" href="#交错-did" aria-label="Permalink to &quot;交错 DiD&quot;">​</a></h1><div class="epigraph"><p>处理时点参差不齐时，双向固定效应把已经处理的组拿来当对照；效应随时间变，则权重可以为负，点估计不再是 ATT 的凸组合。</p><footer>—— Goodman-Bacon, Difference-in-Differences with Variation in Treatment Timing, J. Econometrics 2021；Sun and Abraham, Econometrica 2021；Callaway and Sant&#39;Anna, J. Econometrics 2021</footer></div><p><a href="/econ/difference-in-differences">上一课</a>在两期两组把 DiD 写成平行趋势下的 ATT。本课缺口是采纳时点交错：TWFE 估的不再自动是「所有 \\(2\\times2\\) 的平均」。断点回归下一课换截面设计，不再拆时间加权。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多个组在不同期进入处理，之后通常不退出。TWFE \\(Y_{it}=\\alpha_i+\\lambda_t+\\beta D_{it}+u_{it}\\) 仍可跑。Goodman-Bacon 分解：\\(\\hat\\beta\\) 是所有两期两组 DiD 的加权平均，权重由组规模与处理时点的方差决定。其中一类对照是「后来处理的 vs 已经处理的」。若处理效应随时间加强（动态 ATT），已经处理的组的 \\(Y(1)\\) 还在变，拿它当 \\(Y(0)\\) 的代理会把效应减掉甚至翻号。缺口是：看见 TWFE 的 \\(\\beta\\) 接近零，可能是负权重，不是没有效应。</p><p><span class="marginnote">直觉类比：Bacon 分解像把总成绩拆成多次小测的加权平均——但有些「小测」的权重是负的。拿已经进步的同学当「不补课的基准」，补课效果反而被减掉；权重一旦出现负项，平均数就不再落在各个小测之间。</span></p><p><span class="marginnote">Borusyak、Jaravel 与 Spiess；de Chaisemartin 与 D&#39;Haultfœuille 给出另一套诊断：有多少权重为负、这些权重乘在哪些组上。诊断先于「换一个估计量」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先报告 Bacon 分解或负权重份额。再换目标：组–时平均处理效应 \\(\\mathrm{ATT}(g,t)\\)，只用不曾处理或尚未处理的组当对照。Callaway–Sant&#39;Anna、Sun–Abraham 的 cohort 事件研究、Borusyak 的 imputation（先在未处理格点估 \\(\\alpha_i+\\lambda_t\\) 再外推）都是这一原则的算法。不要用「加组趋势」假装已经解决交错：组线性趋势吸收的是另一类偏离，不是负权重。</p>',9)),(t(),A(l,null,{default:E(()=>[o(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20STAG%5B%22%E4%BA%A4%E9%94%99%E6%97%B6%E7%82%B9%22%5D%20--%3E%20TWFE%5B%22TWFE%20%CE%B2%22%5D%0A%20%20TWFE%20--%3E%20BACON%5B%22Bacon%3A%20%E5%90%AB%E5%B7%B2%E5%A4%84%E7%90%86%E5%BD%93%E5%AF%B9%E7%85%A7%22%5D%0A%20%20DYN%5B%22%E5%8A%A8%E6%80%81%E6%95%88%E5%BA%94%22%5D%20--%3E%20NEG%5B%22%E6%9D%83%E9%87%8D%E5%8F%AF%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20BACON%20--%3E%20NEG%0A%20%20CS%5B%22%E5%B0%9A%E6%9C%AA%E5%A4%84%E7%90%86%E5%BD%93%E5%AF%B9%E7%85%A7%22%5D%20--%3E%20ATT%5B%22ATT(g%2Ct)%20%E5%86%8D%E8%81%9A%E5%90%88%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"平行趋势仍要，只是对照集必须干净。已处理当对照等于假设处理效应在对照窗口里为常数——与动态效应冲突。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是加权。两期两组只有一套差中差。交错产生许多套，TWFE 用残差化 \\(D_{it}\\) 的方差当权重，不保证正。负权重不是软件 bug，是线性投影的代数。换成 \\(\\mathrm{ATT}(g,t)\\) 是换参数：先定义要平均哪些组、哪些时点（政策相关的目标），再估计，而不是让软件挑一组符号不定的权重。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：ATT(g,t) 读作「第 g 期开始接受处理的组，在第 t 期的平均处理效应」。先按组与时间切片，每片用干净对照单独估计，最后按政策关心的权重加总——目标先定，再谈估计。")],-1)),(t(),A(l,null,{default:E(()=>[o(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20EST%5B%22%E8%A6%81%E4%BC%B0%E6%9F%90%E7%BB%84%E5%9C%A8%E6%9F%90%E6%9C%9F%E7%9A%84%E6%95%88%E5%BA%94%22%5D%20--%3E%20Q%7B%22%E6%8B%BF%E8%B0%81%E5%BD%93%E5%AF%B9%E7%85%A7%EF%BC%9F%22%7D%0A%20%20Q%20--%20%22%E5%B7%B2%E5%A4%84%E7%90%86%E7%9A%84%E6%97%A9%E6%9C%9F%E7%BB%84%22%20--%3E%20BAD%5B%22%E5%AE%83%E7%9A%84%20Y(1)%20%E8%BF%98%E5%9C%A8%E5%8F%98%EF%BC%9A%E5%8A%A8%E6%80%81%E6%95%88%E5%BA%94%E6%B7%B7%E8%BF%9B%E5%AF%B9%E7%85%A7%22%5D%0A%20%20BAD%20--%3E%20NEG%5B%22%E5%B7%AE%E4%B8%AD%E5%B7%AE%E8%A2%AB%E6%B1%A1%E6%9F%93%EF%BC%8C%E6%9D%83%E9%87%8D%E5%8F%AF%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20Q%20--%20%22%E5%B0%9A%E6%9C%AA%E5%A4%84%E7%90%86%E6%88%96%E4%B8%8D%E6%9B%BE%E5%A4%84%E7%90%86%22%20--%3E%20OK%5B%22%E5%AE%83%E7%9A%84%20Y(0)%20%E5%B9%B2%E5%87%80%22%5D%0A%20%20OK%20--%3E%20VALID%5B%22ATT(g%2Ct)%20%E5%8F%AF%E4%BF%A1%EF%BC%8C%E5%86%8D%E8%81%9A%E5%90%88%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p>与<a href="/econ/potential-outcomes">潜在结果</a>：交错下 SUTVA 仍在；另外要「无预期」（处理前 \\(D\\) 的信息不应已改变 \\(Y(0)\\)）。预期会把效应提前到事件研究的负期，看起来像预趋势失败。</p><p><span class="marginnote">Sun–Abraham：交互的组–时虚变量再按样本份额加权，避免把后期组的动态和早期组的动态搅在同一条事件研究系数里。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不宣称某一种新估计量在所有设计下最优。不把 2021 年后的每一篇稳健 DiD 写成清单。连续处理、退出处理、多值剂量，代数更脏，本课只标。下一课 RDD 回到截面资格变量，不依赖平行趋势。</p><p><span class="marginnote">常见误区：TWFE 系数接近零就下结论「政策没用」。交错加动态效应时，负权重能把真实的正效应抵成零甚至翻成负号——先做 Bacon 分解查权重，再谈有没有效应。</span></p><p>后课默认：交错采纳禁止默默报告 TWFE 当 ATT；先分解权重，再报告基于干净对照的 \\(\\mathrm{ATT}(g,t)\\)。两期两组上一课仍然成立。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TWFE 在交错下是 \\(2\\times2\\) 的加权，可含已处理对照。</li><li>动态效应 + 负权重 ⇒ 点估计可远离任何凸 ATT。</li><li>目标改成 \\(\\mathrm{ATT}(g,t)\\)，对照只用尚未处理。</li><li>无预期是额外假设；提前反应像假预趋势。</li><li>出处：Goodman-Bacon 2021；Sun and Abraham 2021；Callaway and Sant&#39;Anna 2021；de Chaisemartin and D&#39;Haultfœuille。</li></ul>',8))])}const C=s(m,[["render",p]]);export{f as __pageData,C as default};
